@namespace sv_b77081132d394c288b8862f79a653f8d.Components.Pages.Settings
@using sv_b77081132d394c288b8862f79a653f8d.Services
@inject ISettingsService SettingsService

<div class="card">
    <div class="card-header">
        <h4 class="mb-0">Appearance Settings</h4>
    </div>
    <div class="card-body">
        @if (_loading)
        {
            <div class="text-center py-4">
                <div class="spinner-border" role="status">
                    <span class="visually-hidden">Loading...</span>
                </div>
            </div>
        }
        else
        {
            @if (!string.IsNullOrEmpty(_message))
            {
                <div class="alert alert-success alert-dismissible fade show">
                    @_message
                    <button type="button" class="btn-close" @onclick="() => _message = null"></button>
                </div>
            }

            <div class="row">
                <div class="col-md-7">
                    <h5 class="mb-3">Theme</h5>
                    <div class="mb-3">
                        @foreach (var theme in new[] { "Light", "Dark", "System" })
                        {
                            <div class="form-check">
                                <input class="form-check-input" type="radio" name="theme"
                                       id="theme-@theme" value="@theme"
                                       checked="@(_theme == theme)"
                                       @onchange="() => _theme = theme" />
                                <label class="form-check-label" for="theme-@theme">@theme</label>
                            </div>
                        }
                    </div>

                    <h5 class="mb-3">Font Size</h5>
                    <div class="mb-3">
                        @foreach (var size in new[] { "Small", "Medium", "Large" })
                        {
                            <div class="form-check form-check-inline">
                                <input class="form-check-input" type="radio" name="fontSize"
                                       id="size-@size" value="@size"
                                       checked="@(_fontSize == size)"
                                       @onchange="() => _fontSize = size" />
                                <label class="form-check-label" for="size-@size">@size</label>
                            </div>
                        }
                    </div>

                    <h5 class="mb-3">Language</h5>
                    <div class="mb-3">
                        <select class="form-select" @bind="_language">
                            <option value="en">English</option>
                            <option value="es">Español</option>
                            <option value="fr">Français</option>
                            <option value="de">Deutsch</option>
                            <option value="ja">日本語</option>
                            <option value="zh">中文</option>
                        </select>
                    </div>

                    <h5 class="mb-3">Layout</h5>
                    <div class="mb-3">
                        <div class="form-check form-switch">
                            <input class="form-check-input" type="checkbox" id="compactMode" @bind="_compactMode" />
                            <label class="form-check-label" for="compactMode">Compact Mode</label>
                        </div>
                    </div>

                    <button class="btn btn-primary" @onclick="SaveAsync" disabled="@_saving">
                        @if (_saving)
                        {
                            <span class="spinner-border spinner-border-sm me-1"></span>
                        }
                        Save
                    </button>
                </div>

                <div class="col-md-5">
                    <h5 class="mb-3">Live Preview</h5>
                    <div class="border rounded p-3 @PreviewBackgroundClass" style="min-height: 200px;">
                        <div class="@PreviewTextClass" style="@PreviewFontStyle">
                            <h6 class="@PreviewHeadingClass">Sample Heading</h6>
                            <p class="@(_compactMode ? "mb-1" : "mb-3")">
                                This is how your content will look with the current settings.
                            </p>
                            <div class="d-flex gap-2 @(_compactMode ? "flex-wrap" : "")">
                                <span class="badge @PreviewBadgeClass">Tag 1</span>
                                <span class="badge @PreviewBadgeClass">Tag 2</span>
                                <span class="badge @PreviewBadgeClass">Tag 3</span>
                            </div>
                            <hr class="@(_compactMode ? "my-1" : "my-3")" />
                            <small class="@PreviewMutedClass">Theme: @_theme | Size: @_fontSize | Compact: @(_compactMode ? "On" : "Off")</small>
                        </div>
                    </div>
                </div>
            </div>
        }
    </div>
</div>

@code {
    private bool _loading = true;
    private bool _saving;
    private string? _message;

    private string _theme = "Light";
    private string _fontSize = "Medium";
    private string _language = "en";
    private bool _compactMode;

    protected override async Task OnInitializedAsync()
    {
        _loading = true;
        var settings = await SettingsService.GetAppearanceAsync();
        _theme = settings.Theme;
        _fontSize = settings.FontSize;
        _language = settings.Language;
        _compactMode = settings.CompactMode;
        _loading = false;
    }

